steps.cmd:
mkdir -p /app/output /app/runs && cat > /app/output/gen.py <<'PY'
"""Recorded standard-mode camera/proprioception controller for picking_up_trash.
Run as an interactive JSON-lines controller. All episode calls are recorded.
"""
import sys, json, time, pathlib, traceback
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image, ImageDraw
from rcb_client import Robot, EpisodeOver

out=pathlib.Path('/app/output'); runs=pathlib.Path('/app/runs')
r=Robot(); spec=r.spec()
(out/'spec.json').write_text(json.dumps(spec,indent=2))
print('READY',json.dumps(r.status()),flush=True)
last=None; count=0

def save(res):
    global last,count
    last=res; count+=1
    d=runs/f'{count:03d}'; res.save(str(d))
    np.savez(d/'raw_last.npz', **res.last)
    ims=[]
    for cam,img in res.last.items():
        im=Image.fromarray(img).resize((448,448))
        canv=Image.new('RGB',(448,475),'white');canv.paste(im,(0,27)); ImageDraw.Draw(canv).text((5,5),cam,fill='black');ims.append(canv)
    if ims:
        panel=Image.new('RGB',(448*len(ims),475),'white')
        for i,im in enumerate(ims):panel.paste(im,(448*i,0))
        panel.save(out/'latest.png');panel.save(d/'panel.png')
    meta={k:v for k,v in res.meta.items() if k not in ['cameras','proprio']}
    print('RESULT',count,json.dumps(meta),flush=True)
    print('PROPRIO',json.dumps(dict(zip(res.meta['proprio']['layout'],res.meta['proprio']['now']))),flush=True)
    return res

def joint_now():
    p=dict(zip(last.meta['proprio']['layout'],last.meta['proprio']['now']))
    names=spec['action_types']['joint_position']['layout']
    return np.array([0 if i<3 else p[n] for i,n in enumerate(names)],float)

for line in sys.stdin:
    try:
        cmd=json.loads(line); (out/'commands.jsonl').open('a').write(json.dumps(cmd)+'\n')
        op=cmd['op']
        if op=='obs': save(r.get_obs(depth=True,seconds=cmd.get('seconds',0)))
        elif op=='status':print('STATUS',json.dumps(r.status()),flush=True)
        elif op=='spec':print('SPEC',json.dumps(spec),flush=True)
        elif op=='submit': save(r.submit(cmd['type'],cmd['actions'],dt=cmd.get('dt'),depth=True,video='both',note=cmd.get('note','')))
        elif op=='joint':
            a=joint_now()
            for k,v in cmd.get('set',{}).items(): a[int(k)]=v
            if 'base' in cmd:a[:3]=cmd['base']
            save(r.submit('joint_position',np.tile(a,(cmd.get('n',1),1)),dt=cmd.get('dt',1/30),depth=True,video='both',note=cmd.get('note','')))
        elif op=='ik':print('IK',json.dumps(r.ik(**cmd['args'])),flush=True)
        elif op=='fk':print('FK',json.dumps(r.fk(**cmd['args'])),flush=True)
        elif op=='exit':break
    except EpisodeOver as e: print('EPISODE_OVER',str(e),flush=True)
    except Exception as e:
        print('ERROR',repr(e),flush=True);traceback.print_exc()
        if 'Connection' in type(e).__name__ or (isinstance(e,ValueError) and str(e).startswith(('500','502','503','504'))):
            print('RECOVERY',json.dumps(r.wait_ready()),flush=True);print('STATUS',json.dumps(r.status()),flush=True)
PY
python -u /app/output/gen.py

