cat > /app/output/prepare.py <<'PY'
import json,sys,pathlib,numpy as np
from scipy.spatial.transform import Rotation
ROOT=pathlib.Path('/app/runs')
def latest():return sorted(ROOT.glob('[0-9]*'))[-1]
def state(d=None):
 d=pathlib.Path(d) if d else latest();m=json.load(open(d/'meta.json')); p=dict(zip(m['proprio']['layout'],m['proprio']['now']));return d,m,p
def joints(p):
 names=['torso_joint'+str(i) for i in range(1,5)]+['left_arm_joint'+str(i) for i in range(1,8)]+['left_gripper_finger_joint1','left_gripper_finger_joint2']+['right_arm_joint'+str(i) for i in range(1,8)]+['right_gripper_finger_joint1','right_gripper_finger_joint2'];return np.array([0,0,0]+[p[k] for k in names])
def point(cam,u,v,d=None):
 d,m,p=state(d);cam=next(c for c in m['cameras'] if cam in c);z=np.load(d/f'last_depth_{cam}.npy')[v,u];c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);pc=np.linalg.inv(K)@np.array([u,v,1])*z;return E[:,:3].T@(pc-E[:,3])
if __name__=='__main__':
 op=sys.argv[1];d,m,p=state()
 if op=='point':
  for uv in sys.argv[3:]:u,v=map(int,uv.split(','));print(uv,point(sys.argv[2],u,v).tolist())
 if op=='state':print(json.dumps({k:v for k,v in p.items() if ('vel' not in k and 'effort' not in k and 'footprint' not in k)},indent=1))
 if op=='move':
  a=joints(p);a[:3]=list(map(float,sys.argv[2:5]));n=int(sys.argv[5]);cmd={'op':'submit','type':'joint_position','actions':np.tile(a,(n,1)).tolist(),'dt':1/30};print(json.dumps(cmd))
 if op=='pose':
  side=sys.argv[2];pos=list(map(float,sys.argv[3:6]));quat=list(map(float,sys.argv[6:10])) if len(sys.argv)>6 else [0,1,0,0]
  a=[]
  for s in ['left','right']:a+=[p[s+'_eef_'+k] for k in ['x','y','z','qx','qy','qz','qw']]+[1]
  i=0 if side=='left' else 8;a[i:i+7]=pos+quat;print(json.dumps({'op':'submit','type':'ee_pose','actions':[a]}))
PY
